  case 0xe26au: /* rts */
   if(full_call){CHECK(read_value(&s,s.cpu.registers[15],4,&v));s.cpu.pc=v;pop(&s,4);}*state=s.cpu;return BIWN_GEOMETRY_RECORDS_CPU_OK;
  case 0xe098u: /* cmpi.l #$0, $f03200.l */
   v=0x0u;
